import{_ as n,c as a,a as i,o as l}from"./app-D7XUH6fh.js";const e={};function d(c,s){return l(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="choreographer-中的-trace-事件-函数对应清单" tabindex="-1"><a class="header-anchor" href="#choreographer-中的-trace-事件-函数对应清单"><span>Choreographer 中的 Trace 事件 &amp; 函数对应清单</span></a></h1><blockquote><p>本清单列出 Android Choreographer 中所有的 Trace 事件，以及每个事件对应的函数、函数作用、调用时机、性能影响等信息。</p></blockquote><hr><h2 id="第一层-vsync-驱动信号" tabindex="-1"><a class="header-anchor" href="#第一层-vsync-驱动信号"><span>第一层：VSYNC 驱动信号</span></a></h2><h3 id="_1-1-onvsync-vsync-信号回调" tabindex="-1"><a class="header-anchor" href="#_1-1-onvsync-vsync-信号回调"><span>1.1 onVsync() - VSYNC 信号回调</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ FrameDisplayEventReceiver#onVsync()                      │</span>
<span class="line">│ （在 Perfetto 中显示为蓝色竖线）                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.DisplayEventReceiver.onVsync()             │</span>
<span class="line">│ （FrameDisplayEventReceiver 是 Choreographer 的内部类）  │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 接收来自 SurfaceFlinger 的硬件 VSYNC 信号             │</span>
<span class="line">│ 2. 记录信号到达的精确时间戳：timestampNanos              │</span>
<span class="line">│ 3. 计算本帧的帧时间：frameTimeNanos = timestampNanos     │</span>
<span class="line">│ 4. 发送 Handler 消息：Handler.sendMessage(MSG_DO_FRAME) │</span>
<span class="line">│ 5. UI 线程随后处理消息，调用 Choreographer.doFrame()    │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void onVsync(long timestampNanos, long physicalDisplayId)│</span>
<span class="line">│ {                                                         │</span>
<span class="line">│     mTimestampNanos = timestampNanos;                     │</span>
<span class="line">│     // 发送消息给 UI 线程                                 │</span>
<span class="line">│     mHandler.sendMessageAtTime(msg, timestampNanos);     │</span>
<span class="line">│     // msg 会在 UI 线程触发 Choreographer.doFrame()      │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 调用时机                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 硬件 VSYNC 信号到达时（60Hz: 每 16.67ms）             │</span>
<span class="line">│ • 120Hz 屏幕：每 8.33ms                                  │</span>
<span class="line">│ • 144Hz 屏幕：每 6.94ms                                  │</span>
<span class="line">│ • **仅在 Mode 1 (USE_VSYNC=true) 时出现**                │</span>
<span class="line">│ • Mode 2 (定时器模式) 中看不到这个事件                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 执行耗时：微秒级（&lt;0.01ms）                             │</span>
<span class="line">│ • 间隔精度：±0.1ms（硬件提供）                            │</span>
<span class="line">│ • 关键指标：精确度（60Hz 应该是 16.67ms 的倍数）         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：细细的蓝色竖线                                    │</span>
<span class="line">│ • 位置：UI 线程轨迹上，整个帧处理之前                     │</span>
<span class="line">│ • 间隔：精确均匀（Mode 1）或不均匀（Mode 2）             │</span>
<span class="line">│ • 标签：FrameDisplayEventReceiver::onVsync()             │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 例：                                                      │</span>
<span class="line">│ ├─ [16.67ms] onVsync()                                   │</span>
<span class="line">│ ├─ [33.34ms] onVsync()                                   │</span>
<span class="line">│ ├─ [50.01ms] onVsync()  ← 精确间隔，Mode 1 的表现         │</span>
<span class="line">│ └─ ...                                                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: onVsync() 看不到？                                    │</span>
<span class="line">│ A: 可能是 Mode 2 (USE_VSYNC=false)，检查系统属性         │</span>
<span class="line">│    adb shell getprop debug.choreographer.vsync           │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: onVsync() 间隔不均匀（15ms, 17ms）？                  │</span>
<span class="line">│ A: Mode 2 定时器精度差，或硬件 VSYNC 异常               │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: onVsync() 和 doFrame() 之间有延迟？                   │</span>
<span class="line">│ A: UI 线程繁忙，Handler 消息在队列中等待                 │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="第二层-doframe-帧处理核心函数" tabindex="-1"><a class="header-anchor" href="#第二层-doframe-帧处理核心函数"><span>第二层：doFrame() - 帧处理核心函数</span></a></h2><h3 id="_2-1-doframe-本帧处理开始" tabindex="-1"><a class="header-anchor" href="#_2-1-doframe-本帧处理开始"><span>2.1 doFrame() - 本帧处理开始</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Choreographer#doFrame()                                  │</span>
<span class="line">│ （在 Perfetto 中显示为绿色/红色 bar）                    │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.doFrame(long frameTimeNanos) │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 保存当前帧时间                                         │</span>
<span class="line">│    mLastFrameTimeNanos = frameTimeNanos                  │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 2. 依次调用 5 大回调队列（顺序不可变）：                  │</span>
<span class="line">│    ├─ doCallbacks(CALLBACK_INPUT, frameTimeNanos)        │</span>
<span class="line">│    ├─ doCallbacks(CALLBACK_ANIMATION, frameTimeNanos)    │</span>
<span class="line">│    ├─ doCallbacks(CALLBACK_INSETS_ANIMATION, ...)        │</span>
<span class="line">│    ├─ doCallbacks(CALLBACK_TRAVERSAL, frameTimeNanos)    │</span>
<span class="line">│    └─ doCallbacks(CALLBACK_COMMIT, frameTimeNanos)       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 3. 调度下一帧（如果有待执行回调或 VSYNC 已注册）         │</span>
<span class="line">│    scheduleFrame()                                       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void doFrame(long frameTimeNanos) {                      │</span>
<span class="line">│     // 1. 保存帧时间                                     │</span>
<span class="line">│     mLastFrameTimeNanos = frameTimeNanos;                │</span>
<span class="line">│                                                          │</span>
<span class="line">│     // 2. 执行 5 大回调（顺序严格）                       │</span>
<span class="line">│     doCallbacks(CALLBACK_INPUT, frameTimeNanos);         │</span>
<span class="line">│     doCallbacks(CALLBACK_ANIMATION, frameTimeNanos);     │</span>
<span class="line">│     doCallbacks(CALLBACK_INSETS_ANIMATION, ...);         │</span>
<span class="line">│     doCallbacks(CALLBACK_TRAVERSAL, frameTimeNanos);     │</span>
<span class="line">│     doCallbacks(CALLBACK_COMMIT, frameTimeNanos);        │</span>
<span class="line">│                                                          │</span>
<span class="line">│     // 3. 如果有新的回调或 VSYNC 未注册，调度下一帧       │</span>
<span class="line">│     if (mCallbackQueues need scheduling) {              │</span>
<span class="line">│         scheduleFrame();                                 │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 调用时机                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 由 onVsync() 发送的 Handler 消息触发                    │</span>
<span class="line">│ • 或由定时器到期触发（Mode 2）                            │</span>
<span class="line">│ • 通常每 16ms 调用一次（60Hz）                           │</span>
<span class="line">│ • 120Hz 屏幕每 8.33ms 调用一次                           │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 耗时预算：16ms（60Hz）/ 8.33ms（120Hz）                │</span>
<span class="line">│ • 关键指标：超时 = Jank（&gt;16ms）                          │</span>
<span class="line">│ • 分布：INPUT(1ms) + ANIM(3ms) + INSETS(1ms) +          │</span>
<span class="line">│         TRAVERSAL(8ms) + COMMIT(2ms) = ~15ms             │</span>
<span class="line">│ • 缓冲：约 1ms 的安全边界                                │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：                                                  │</span>
<span class="line">│   ├─ 绿色 bar：正常（&lt;16ms）                             │</span>
<span class="line">│   ├─ 红色 bar：超时（&gt;16ms），Jank 发生                  │</span>
<span class="line">│   └─ 橙色 bar：接近超时（15-16ms）                       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ • 位置：UI 线程轨迹上，onVsync() 之后                     │</span>
<span class="line">│ • 宽度：帧处理耗时（越窄越好）                            │</span>
<span class="line">│ • 标签：Choreographer::doFrame                           │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 例：                                                      │</span>
<span class="line">│ ├─ [████] doFrame (12ms) ✅ 正常                         │</span>
<span class="line">│ ├─ [████████████] doFrame (18ms) ❌ Jank                │</span>
<span class="line">│ └─ [███] doFrame (8ms) ✅ 很快                           │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: doFrame 是红色（Jank）？                              │</span>
<span class="line">│ A: 找到红色段内部哪个阶段最长，那就是瓶颈                │</span>
<span class="line">│    • TRAVERSAL 长 → View 树太复杂                        │</span>
<span class="line">│    • ANIMATION 长 → 动画计算复杂                         │</span>
<span class="line">│    • INPUT 长 → 输入处理需优化                           │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: doFrame 耗时波动很大？                                │</span>
<span class="line">│ A: 可能有动态内容（不同帧的 View 树复杂度不同）          │</span>
<span class="line">│    或内存压力（GC 暂停）                                 │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: doFrame 一直是绿色，为什么还是卡顿？                  │</span>
<span class="line">│ A: 可能是后续的 SurfaceFlinger 处理耗时                  │</span>
<span class="line">│    或缓冲区堆积导致的显示延迟                             │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="第三层-5-大回调阶段" tabindex="-1"><a class="header-anchor" href="#第三层-5-大回调阶段"><span>第三层：5 大回调阶段</span></a></h2><h3 id="_3-1-input-回调-处理输入事件" tabindex="-1"><a class="header-anchor" href="#_3-1-input-回调-处理输入事件"><span>3.1 INPUT 回调 - 处理输入事件</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Choreographer#doFrame -&gt; INPUT                           │</span>
<span class="line">│ （嵌套在 doFrame 内）                                    │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.doCallbacks(               │</span>
<span class="line">│     int callbackType = CALLBACK_INPUT,                  │</span>
<span class="line">│     long frameTimeNanos                                 │</span>
<span class="line">│ )                                                        │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 从 mCallbackQueues[CALLBACK_INPUT] 取出所有回调       │</span>
<span class="line">│ 2. 遍历执行每一个回调：action.run()                      │</span>
<span class="line">│ 3. 这些 run() 内部处理各种输入事件                        │</span>
<span class="line">│    • 触摸事件（MotionEvent）                             │</span>
<span class="line">│    • 按键事件（KeyEvent）                                │</span>
<span class="line">│    • 焦点变化等                                          │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void doCallbacks(int callbackType, long frameTimeNanos) │</span>
<span class="line">│ {                                                         │</span>
<span class="line">│     CallbackRecord[] callbacks =                         │</span>
<span class="line">│         mCallbackQueues[callbackType].mHead;             │</span>
<span class="line">│     while (callbacks != null) {                          │</span>
<span class="line">│         callbacks.run(frameTimeNanos);  // 执行回调       │</span>
<span class="line">│         callbacks = callbacks.next;                      │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 典型回调来源                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • InputManagerService（处理触摸、按键）                   │</span>
<span class="line">│ • View#dispatchTouchEvent()（View 层处理）               │</span>
<span class="line">│ • GestureDetector（手势识别）                            │</span>
<span class="line">│ • InputEventListener                                     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 典型耗时：1ms                                          │</span>
<span class="line">│ • 最大预算：2-3ms（超过则可能导致输入卡顿）              │</span>
<span class="line">│ • 关键指标：应该是 5 大回调中最快的                       │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：doFrame 内的第 1 段小 bar                        │</span>
<span class="line">│ • 位置：5 大回调中最前                                    │</span>
<span class="line">│ • 宽度：通常很小（约 1px）                               │</span>
<span class="line">│ • 标签：Choreographer::doFrame -&gt; INPUT                  │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: INPUT 段很长（&gt;2ms）？                                │</span>
<span class="line">│ A: 输入处理耗时，可能是：                                 │</span>
<span class="line">│    • View#onTouchEvent() 中的复杂逻辑                    │</span>
<span class="line">│    • GestureDetector 计算耗时                            │</span>
<span class="line">│    • 在 INPUT 阶段做了不该做的操作                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 触摸操作响应卡顿？                                     │</span>
<span class="line">│ A: 检查前一帧的 TRAVERSAL 是否超时                        │</span>
<span class="line">│    如果前一帧 Jank，这一帧的 INPUT 会被延迟               │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-animation-回调-更新动画值" tabindex="-1"><a class="header-anchor" href="#_3-2-animation-回调-更新动画值"><span>3.2 ANIMATION 回调 - 更新动画值</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Choreographer#doFrame -&gt; ANIMATION                       │</span>
<span class="line">│ （嵌套在 doFrame 内）                                    │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.doCallbacks(               │</span>
<span class="line">│     int callbackType = CALLBACK_ANIMATION,              │</span>
<span class="line">│     long frameTimeNanos                                 │</span>
<span class="line">│ )                                                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 最终调用：                                                │</span>
<span class="line">│ android.animation.AnimationHandler.doAnimationFrame()    │</span>
<span class="line">│ android.animation.ValueAnimator.doAnimationFrame()       │</span>
<span class="line">│ android.animation.ObjectAnimator.onAnimationUpdate()     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 从 mCallbackQueues[CALLBACK_ANIMATION] 取回调         │</span>
<span class="line">│ 2. 执行动画回调（通常是 AnimationHandler）               │</span>
<span class="line">│ 3. AnimationHandler.doAnimationFrame() 内部：            │</span>
<span class="line">│    a) 遍历所有正在运行的动画                              │</span>
<span class="line">│    b) 对每个动画调用 animator.doAnimationFrame()         │</span>
<span class="line">│    c) 在 doAnimationFrame() 中：                         │</span>
<span class="line">│       • 计算动画进度：progress = (now - startTime) / dur │</span>
<span class="line">│       • 应用插值器：progress = interpolator.apply(prog)  │</span>
<span class="line">│       • 调用回调：animationListener.onAnimationUpdate()  │</span>
<span class="line">│       • 更新 View 属性：view.setTranslationX()等         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void doAnimationFrame(long frameTimeNanos) {             │</span>
<span class="line">│     for (Animator anim : mRunningAnimators) {            │</span>
<span class="line">│         long elapsedTime = frameTimeNanos - startTime;   │</span>
<span class="line">│         float progress = elapsedTime / duration;         │</span>
<span class="line">│         progress = interpolator.apply(progress);         │</span>
<span class="line">│         anim.onAnimationUpdate(progress); // 更新值      │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 典型回调来源                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • ValueAnimator（属性动画框架）                           │</span>
<span class="line">│ • ObjectAnimator（直接操作 View 属性）                    │</span>
<span class="line">│ • View#postOnAnimation()（View 自定义动画）              │</span>
<span class="line">│ • Animator（过渡动画）                                    │</span>
<span class="line">│ • 用户自定义的 FrameCallback                              │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 典型耗时：2-5ms（取决于动画数量和复杂度）              │</span>
<span class="line">│ • 关键指标：计算进度和应用值的耗时                        │</span>
<span class="line">│ • 最大预算：6-7ms（超过则影响 TRAVERSAL）                │</span>
<span class="line">│ • 关键度量：每个动画的回调耗时（应该 &lt;0.1ms）            │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：doFrame 内的第 2 段 bar                          │</span>
<span class="line">│ • 位置：在 INPUT 之后，TRAVERSAL 之前                     │</span>
<span class="line">│ • 宽度：中等（通常 2-5px）                                │</span>
<span class="line">│ • 标签：Choreographer::doFrame -&gt; ANIMATION              │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 如果看到 ANIMATION 段内有波动：                           │</span>
<span class="line">│ ├─ 可能是因为动画计算导致的帧时间变化                     │</span>
<span class="line">│ └─ 检查是否使用了 System.nanoTime() 而非 frameTime        │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: ANIMATION 段很长（&gt;5ms）？                            │</span>
<span class="line">│ A: 可能原因：                                             │</span>
<span class="line">│    • 运行中的动画太多                                     │</span>
<span class="line">│    • 每个动画的回调都很耗时                               │</span>
<span class="line">│    • 使用了复杂的插值器（计算密集）                       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 动画不平滑、有 pop/卡顿？                              │</span>
<span class="line">│ A: 最常见的原因是在动画回调中使用了 System.nanoTime()    │</span>
<span class="line">│    改用：Choreographer.getInstance().getFrameTime()     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: ANIMATION 段耗时波动很大？                            │</span>
<span class="line">│ A: 可能是：                                               │</span>
<span class="line">│    • 某些帧的动画计算复杂（如计算路径、alpha混合）        │</span>
<span class="line">│    • 或 GC 暂停导致                                      │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-insets-animation-回调-窗口-insets-动画" tabindex="-1"><a class="header-anchor" href="#_3-3-insets-animation-回调-窗口-insets-动画"><span>3.3 INSETS_ANIMATION 回调 - 窗口 Insets 动画</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Choreographer#doFrame -&gt; INSETS_ANIMATION               │</span>
<span class="line">│ （嵌套在 doFrame 内）                                    │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.doCallbacks(               │</span>
<span class="line">│     int callbackType = CALLBACK_INSETS_ANIMATION,       │</span>
<span class="line">│     long frameTimeNanos                                 │</span>
<span class="line">│ )                                                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 最终调用：                                                │</span>
<span class="line">│ android.view.WindowInsetsController.onFrameUpdate()      │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 更新窗口 Insets 的动画进度                            │</span>
<span class="line">│ 2. Insets 典型场景：                                      │</span>
<span class="line">│    • 输入法（IME）出现/消失                               │</span>
<span class="line">│    • 系统导航栏出现/消失                                  │</span>
<span class="line">│    • 状态栏出现/消失                                      │</span>
<span class="line">│ 3. 按帧更新 Insets 的底部/顶部/左侧/右侧偏移             │</span>
<span class="line">│ 4. 通知 View 树更新布局                                  │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void onFrameUpdate(long frameTimeNanos) {                │</span>
<span class="line">│     // 计算 Insets 动画进度                               │</span>
<span class="line">│     float progress = calculateProgress(frameTimeNanos);  │</span>
<span class="line">│     // 更新每个边的 Insets 值                             │</span>
<span class="line">│     int bottom = startInsets + (endInsets - startInsets) │</span>
<span class="line">│                  * progress;                             │</span>
<span class="line">│     // 通知 View 进行 layout 更新                         │</span>
<span class="line">│     dispatchWindowInsetsChangedIfNeeded(bottom);         │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 典型回调来源                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • WindowInsetsController（系统 Insets 控制）             │</span>
<span class="line">│ • InputMethodManager（输入法管理）                       │</span>
<span class="line">│ • WindowInsetsAnimationController                        │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 典型耗时：1ms（通常很快）                              │</span>
<span class="line">│ • 最大预算：2ms                                          │</span>
<span class="line">│ • 关键指标：每帧是否有 Insets 动画在进行                  │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：doFrame 内的第 3 段小 bar                        │</span>
<span class="line">│ • 位置：在 ANIMATION 之后，TRAVERSAL 之前                 │</span>
<span class="line">│ • 宽度：通常很小（约 1px，或看不到）                     │</span>
<span class="line">│ • 标签：Choreographer::doFrame -&gt; INSETS_ANIMATION       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 注：如果没有 Insets 动画（常见），这段 bar 可能不显示     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: 输入法弹出/消失时卡顿？                                │</span>
<span class="line">│ A: 检查 INSETS_ANIMATION 后的 TRAVERSAL 是否超时         │</span>
<span class="line">│    INSETS 变化会触发新的 layout，可能导致 Jank            │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 看不到 INSETS_ANIMATION 段？                          │</span>
<span class="line">│ A: 正常，说明当前没有 Insets 动画在进行                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-traversal-回调-view-树遍历-最耗时-⭐" tabindex="-1"><a class="header-anchor" href="#_3-4-traversal-回调-view-树遍历-最耗时-⭐"><span>3.4 TRAVERSAL 回调 - View 树遍历（最耗时）⭐</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Choreographer#doFrame -&gt; TRAVERSAL                       │</span>
<span class="line">│ （嵌套在 doFrame 内，最长的段）                          │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.doCallbacks(               │</span>
<span class="line">│     int callbackType = CALLBACK_TRAVERSAL,              │</span>
<span class="line">│     long frameTimeNanos                                 │</span>
<span class="line">│ )                                                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ → ViewRootImpl.mTraversalRunnable.run()                  │</span>
<span class="line">│ → ViewRootImpl.doTraversal()                             │</span>
<span class="line">│   ├─ performMeasure(child.getMeasuredWidth/Height)      │</span>
<span class="line">│   ├─ performLayout(l, t, r, b)                          │</span>
<span class="line">│   └─ performDraw(canvas)                                │</span>
<span class="line">│                                                          │</span>
<span class="line">│ → View.measure(widthMeasureSpec, heightMeasureSpec)     │</span>
<span class="line">│ → View.layout(left, top, right, bottom)                 │</span>
<span class="line">│ → View.draw(canvas)                                     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ → RenderNode.endAllUpdates()（提交绘制到 GPU）           │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ ** 这是最复杂、最耗时的阶段 **                            │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 1. ViewRootImpl.doTraversal()：                          │</span>
<span class="line">│    ├─ 调用 performMeasure()                             │</span>
<span class="line">│    ├─ 调用 performLayout()                              │</span>
<span class="line">│    └─ 调用 performDraw()                                │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 2. performMeasure()：                                   │</span>
<span class="line">│    ├─ 从 DecorView（顶级 View）开始                     │</span>
<span class="line">│    ├─ 递归调用每个 View.measure()                        │</span>
<span class="line">│    ├─ 计算每个 View 的宽高（考虑约束和内容）             │</span>
<span class="line">│    └─ 耗时：通常 2-4ms（可能更多如果布局复杂）           │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 3. performLayout()：                                    │</span>
<span class="line">│    ├─ 从 DecorView（顶级 View）开始                     │</span>
<span class="line">│    ├─ 递归调用每个 View.layout()                         │</span>
<span class="line">│    ├─ 根据 measure 结果放置 View 的位置                  │</span>
<span class="line">│    └─ 耗时：通常 1-2ms                                  │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 4. performDraw()：                                      │</span>
<span class="line">│    ├─ 获取 Canvas（硬件加速或软件渲染）                  │</span>
<span class="line">│    ├─ 递归调用每个 View.draw()                           │</span>
<span class="line">│    ├─ 绘制 View（背景、内容、子 View 等）                │</span>
<span class="line">│    ├─ 对于硬件加速，生成 DisplayList（RenderNode）      │</span>
<span class="line">│    ├─ 提交到 GPU（skia 或 Vulkan）                      │</span>
<span class="line">│    └─ 耗时：通常 4-6ms（可能更多如果有复杂绘制）         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void doTraversal() {                                    │</span>
<span class="line">│     performMeasure(                                     │</span>
<span class="line">│         MeasureSpec.makeMeasureSpec(width, EXACTLY)     │</span>
<span class="line">│     );                                                  │</span>
<span class="line">│     performLayout(                                      │</span>
<span class="line">│         0, 0, width, height                             │</span>
<span class="line">│     );                                                  │</span>
<span class="line">│     performDraw();                                      │</span>
<span class="line">│ }                                                         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ void performMeasure(int widthMeasureSpec, ...) {        │</span>
<span class="line">│     mView.measure(widthMeasureSpec, heightMeasureSpec); │</span>
<span class="line">│     // mView 是 DecorView                               │</span>
<span class="line">│     // 递归下去测量所有子 View                            │</span>
<span class="line">│ }                                                         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ void performLayout(int l, int t, int r, int b) {       │</span>
<span class="line">│     mView.layout(l, t, r, b);                           │</span>
<span class="line">│     // mView 是 DecorView                               │</span>
<span class="line">│     // 递归下去放置所有子 View                            │</span>
<span class="line">│ }                                                         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ void performDraw() {                                    │</span>
<span class="line">│     Surface surface = mSurface;                         │</span>
<span class="line">│     Canvas canvas = surface.lockCanvas();               │</span>
<span class="line">│     mView.draw(canvas);  // 递归绘制                    │</span>
<span class="line">│     surface.unlockCanvasAndPost(canvas);                │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 子事件（嵌套在 TRAVERSAL 内）                            │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│                                                          │</span>
<span class="line">│ a) performMeasure                                       │</span>
<span class="line">│    对应函数：ViewRootImpl.performMeasure()               │</span>
<span class="line">│    含义：测量所有 View 的宽高                            │</span>
<span class="line">│    耗时：2-4ms 典型                                     │</span>
<span class="line">│    影响：布局层级深、内容复杂会增加耗时                   │</span>
<span class="line">│                                                          │</span>
<span class="line">│ b) performLayout                                        │</span>
<span class="line">│    对应函数：ViewRootImpl.performLayout()                │</span>
<span class="line">│    含义：计算所有 View 的位置坐标                        │</span>
<span class="line">│    耗时：1-2ms 典型                                     │</span>
<span class="line">│    影响：布局计算复杂（权重、约束等）会增加               │</span>
<span class="line">│                                                          │</span>
<span class="line">│ c) performDraw                                          │</span>
<span class="line">│    对应函数：ViewRootImpl.performDraw()                  │</span>
<span class="line">│    含义：绘制所有 View 到 Canvas                         │</span>
<span class="line">│    耗时：4-6ms 典型                                     │</span>
<span class="line">│    影响：绘制操作复杂（阴影、圆角、滤镜等）会增加         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ d) measure (单个 View 级别)                             │</span>
<span class="line">│    对应函数：View.onMeasure()                            │</span>
<span class="line">│    含义：单个 View 计算自己的宽高                        │</span>
<span class="line">│    耗时：&lt;0.1ms（通常很快）                              │</span>
<span class="line">│    深度：可能有数十次调用（树状递归）                     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ e) layout (单个 View 级别)                              │</span>
<span class="line">│    对应函数：View.onLayout()                             │</span>
<span class="line">│    含义：单个 View 放置自己和子 View 的位置              │</span>
<span class="line">│    耗时：&lt;0.1ms（通常很快）                              │</span>
<span class="line">│    深度：可能有数十次调用（树状递归）                     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ f) draw (单个 View 级别)                                │</span>
<span class="line">│    对应函数：View.onDraw()                               │</span>
<span class="line">│    含义：单个 View 绘制自己                              │</span>
<span class="line">│    耗时：0.01-1ms（取决于绘制复杂度）                    │</span>
<span class="line">│    深度：可能有数十次调用（树状递归）                     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 典型耗时分布（以 Activity 为例）                          │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ TRAVERSAL 总耗时：~8-10ms（在 16ms 预算中占 50-60%）    │</span>
<span class="line">│   ├─ performMeasure：~30-35% (3-4ms)                    │</span>
<span class="line">│   ├─ performLayout：~10-15% (1-2ms)                     │</span>
<span class="line">│   └─ performDraw：~45-50% (4-6ms)                       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 如果布局复杂：                                            │</span>
<span class="line">│   ├─ performMeasure：可能达到 6-8ms（深层级布局）        │</span>
<span class="line">│   ├─ performLayout：可能达到 3-4ms（权重计算）           │</span>
<span class="line">│   └─ performDraw：可能达到 8-10ms（复杂绘制）            │</span>
<span class="line">│   → 总计：15-20ms（超过 16ms，Jank）                    │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 典型耗时：8-10ms                                       │</span>
<span class="line">│ • 最大预算：10-11ms（留空间给其他阶段）                   │</span>
<span class="line">│ • 关键指标：如果 &gt;10ms，下一帧会 Jank                     │</span>
<span class="line">│ • 关键度量：                                              │</span>
<span class="line">│   ├─ View 树深度（应 &lt;10 层）                             │</span>
<span class="line">│   ├─ 单帧 View 总数（应 &lt;100）                            │</span>
<span class="line">│   ├─ 绘制操作复杂度（阴影、滤镜数）                       │</span>
<span class="line">│   └─ Insets 变化频率（会触发额外的 measure/layout）      │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：doFrame 内最长的 bar（占 40-60% 的宽度）         │</span>
<span class="line">│ • 颜色：                                                  │</span>
<span class="line">│   ├─ 绿色：&lt;10ms（正常）                                │</span>
<span class="line">│   ├─ 橙色：10-12ms（接近超时）                          │</span>
<span class="line">│   └─ 红色：&gt;12ms（Jank，严重超时）                      │</span>
<span class="line">│ • 位置：在 INPUT/ANIMATION/INSETS 之后，COMMIT 之前      │</span>
<span class="line">│ • 标签：Choreographer::doFrame -&gt; TRAVERSAL              │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 子 bar：                                                  │</span>
<span class="line">│   ├─ performMeasure bar（约占 30-40%）                  │</span>
<span class="line">│   ├─ performLayout bar（约占 10-15%）                   │</span>
<span class="line">│   └─ performDraw bar（约占 45-50%）                     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 例：                                                      │</span>
<span class="line">│ doFrame (15ms) ❌                                        │</span>
<span class="line">│   ├─ INPUT (0.5ms)                                      │</span>
<span class="line">│   ├─ ANIMATION (2ms)                                    │</span>
<span class="line">│   ├─ INSETS (0.2ms)                                     │</span>
<span class="line">│   ├─ TRAVERSAL (11ms) ← 红色，超时                      │</span>
<span class="line">│   │  ├─ performMeasure (4ms)                            │</span>
<span class="line">│   │  ├─ performLayout (2ms)                             │</span>
<span class="line">│   │  └─ performDraw (5ms) ← 这部分最耗时                │</span>
<span class="line">│   └─ COMMIT (1.3ms)                                     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断（优化方向）                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: TRAVERSAL 是红色（超时）？                            │</span>
<span class="line">│ A: 深入看是哪个子阶段最长：                               │</span>
<span class="line">│    • performMeasure 最长 → 布局层级太深或宽度计算复杂     │</span>
<span class="line">│    • performLayout 最长 → 布局权重计算或约束求解耗时      │</span>
<span class="line">│    • performDraw 最长 → 绘制操作复杂（阴影、圆角等）      │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: measure 耗时很长？                                    │</span>
<span class="line">│ A: 原因通常是：                                           │</span>
<span class="line">│    • View 树太深（递归层数多）→ 扁平化布局                │</span>
<span class="line">│    • View 数量太多（100+ Views）→ 减少 View 数量          │</span>
<span class="line">│    • 动态大小计算（如 wrap_content）→ 使用固定大小         │</span>
<span class="line">│    • 权重计算（LinearLayout with weights）→ 减少权重      │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: layout 耗时很长？                                     │</span>
<span class="line">│ A: 原因通常是：                                           │</span>
<span class="line">│    • 约束求解复杂 → 使用 ConstraintLayout 的引擎优化      │</span>
<span class="line">│    • Frame 嵌套太多 → 扁平化                             │</span>
<span class="line">│    • 滚动视图嵌套 → 避免多层 ScrollView                   │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: draw 耗时很长？                                       │</span>
<span class="line">│ A: 原因通常是：                                           │</span>
<span class="line">│    • 阴影（drop shadow）→ 缓存或预渲染                   │</span>
<span class="line">│    • 圆角（border radius）→ 使用纹理或预裁剪              │</span>
<span class="line">│    • 滤镜效果 → 性能最差，避免实时应用                    │</span>
<span class="line">│    • 自定义绘制（onDraw）→ 优化绘制算法                   │</span>
<span class="line">│    • 图片缩放/旋转 → 预处理到正确尺寸                     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 打开/关闭某个 View 时 Jank？                          │</span>
<span class="line">│ A: 可能是 Visibility 变化触发的 measure/layout             │</span>
<span class="line">│    一次性显示/隐藏多个 View 时尤其明显                    │</span>
<span class="line">│    解决：使用 setAnimationCacheEnabled() 或分帧处理       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 列表滚动时 Jank？                                     │</span>
<span class="line">│ A: 通常是 RecyclerView 中 onDraw 太复杂，或：             │</span>
<span class="line">│    • 列表项布局太复杂                                     │</span>
<span class="line">│    • onBindViewHolder 中做了重操作                        │</span>
<span class="line">│    • 图片加载导致的 measure/layout                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 优化建议：                                                 │</span>
<span class="line">│ 1. 使用 Layout Inspector 查看 View 树深度                │</span>
<span class="line">│ 2. 在 Perfetto 中启用 &quot;Layout Profiling&quot;                 │</span>
<span class="line">│ 3. 使用 android:debugLayout=&quot;true&quot; 查看过度绘制          │</span>
<span class="line">│ 4. 使用 Choreographer.getInstance().getFrameIntervalNanos()│</span>
<span class="line">│ 5. 定期测试：adb shell dumpsys gfxinfo                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-commit-回调-缓冲区提交" tabindex="-1"><a class="header-anchor" href="#_3-5-commit-回调-缓冲区提交"><span>3.5 COMMIT 回调 - 缓冲区提交</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Choreographer#doFrame -&gt; COMMIT                          │</span>
<span class="line">│ （嵌套在 doFrame 内，最后一段）                          │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.doCallbacks(               │</span>
<span class="line">│     int callbackType = CALLBACK_COMMIT,                 │</span>
<span class="line">│     long frameTimeNanos                                 │</span>
<span class="line">│ )                                                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ → HardwareRenderer.commit()（或 ThreadedRenderer）       │</span>
<span class="line">│ → Surface.unlockCanvasAndPost()                         │</span>
<span class="line">│ → BufferQueue::queueBuffer() (SurfaceFlinger 侧)         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 完成所有绘制操作                                       │</span>
<span class="line">│ 2. 如果是硬件加速：                                       │</span>
<span class="line">│    • 所有 RenderNode 已生成                               │</span>
<span class="line">│    • 提交到 GPU 的 DisplayList                            │</span>
<span class="line">│    • GPU 开始执行渲染（异步）                             │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 3. 如果是软件渲染：                                       │</span>
<span class="line">│    • Canvas 的所有绘制已完成                              │</span>
<span class="line">│    • 缓冲区数据准备好                                     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 4. 通知 SurfaceFlinger：                                 │</span>
<span class="line">│    • 缓冲区已就绪，可以合成显示                           │</span>
<span class="line">│    • 传递 present time（预期显示时间）                    │</span>
<span class="line">│    • SurfaceFlinger 在下一个 VSYNC 显示这个缓冲区         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void commit() {                                          │</span>
<span class="line">│     if (hardwareAccelerated) {                           │</span>
<span class="line">│         mRenderNode.endRecording();  // 完成 DisplayList  │</span>
<span class="line">│         // GPU 异步渲染                                  │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│     // 通知 SurfaceFlinger 缓冲区就绪                     │</span>
<span class="line">│     mSurface.unlockCanvasAndPost();                      │</span>
<span class="line">│     // 等待 GPU 完成（可能需要 sync）                     │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 典型耗时：1-2ms                                        │</span>
<span class="line">│ • 最大预算：3ms                                          │</span>
<span class="line">│ • 关键指标：如果超过 3ms，可能说明 GPU 繁忙              │</span>
<span class="line">│ • 关键度量：GPU 帧时间（通过 GPU Profiler 查看）         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：doFrame 内的最后一段小 bar                       │</span>
<span class="line">│ • 位置：在 TRAVERSAL 之后，doFrame 结束前                 │</span>
<span class="line">│ • 宽度：通常很小（1-2px）                                │</span>
<span class="line">│ • 标签：Choreographer::doFrame -&gt; COMMIT                 │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 注：COMMIT 阶段的耗时如果长，可能说明：                   │</span>
<span class="line">│   • GPU 队列堆积（GPU 太忙）                              │</span>
<span class="line">│   • 等待 GPU fence（前一帧 GPU 还没完成）                 │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: COMMIT 段很长（&gt;2ms）？                               │</span>
<span class="line">│ A: 可能原因：                                             │</span>
<span class="line">│    • GPU 繁忙（上一帧还在渲染）                           │</span>
<span class="line">│    • TRAVERSAL 的绘制操作太复杂                           │</span>
<span class="line">│    • 缓冲区堆积（SurfaceFlinger 还没显示上一帧）          │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: GPU profiler 显示 GPU 帧时间很长？                    │</span>
<span class="line">│ A: 检查：                                                 │</span>
<span class="line">│    • 是否有大量的纹理操作                                 │</span>
<span class="line">│    • 是否频繁切换 GPU 着色器                              │</span>
<span class="line">│    • 是否有阴影、滤镜等复杂效果                           │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="第四层-帧调度相关" tabindex="-1"><a class="header-anchor" href="#第四层-帧调度相关"><span>第四层：帧调度相关</span></a></h2><h3 id="_4-1-schedulevsynclocked-注册下一个-vsync" tabindex="-1"><a class="header-anchor" href="#_4-1-schedulevsynclocked-注册下一个-vsync"><span>4.1 scheduleVsyncLocked - 注册下一个 VSYNC</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ scheduleVsyncLocked                                      │</span>
<span class="line">│ （Trace 事件很短，可能看不到）                           │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.scheduleVsyncLocked()        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 调用链：                                                  │</span>
<span class="line">│ → DisplayEventReceiver.scheduleVsync()                   │</span>
<span class="line">│ → nativeScheduleVsync() (JNI)                            │</span>
<span class="line">│ → FrameDisplayEventReceiver (native 对象)                │</span>
<span class="line">│ → displayEventControl-&gt;requestNextVsync() (SurfaceFlinger)│</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 1. 检查是否已注册 VSYNC（避免重复注册）                   │</span>
<span class="line">│ 2. 如果还没有注册，向 SurfaceFlinger 说：                │</span>
<span class="line">│    &quot;我想要下一个 VSYNC 信号&quot;                             │</span>
<span class="line">│ 3. SurfaceFlinger 会在下一个 VSYNC 发生时回调 onVsync()  │</span>
<span class="line">│ 4. 这个调用通常是同步且快速的（JNI 调用）                │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void scheduleVsyncLocked() {                             │</span>
<span class="line">│     if (mVsyncScheduled) {                               │</span>
<span class="line">│         return;  // 已经注册，无需重复                    │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│     // 向 SurfaceFlinger 注册 VSYNC 信号请求              │</span>
<span class="line">│     mDisplayEventReceiver.scheduleVsync();               │</span>
<span class="line">│     mVsyncScheduled = true;                              │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 调用时机                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • doFrame() 即将结束时                                    │</span>
<span class="line">│ • 如果还有待执行的回调或 VSYNC 未注册                     │</span>
<span class="line">│ • Mode 1 (USE_VSYNC=true) 时                             │</span>
<span class="line">│ • 典型频率：每 16ms 左右调用一次                          │</span>
<span class="line">│ • Mode 2 (定时器模式) 不调用此函数                        │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 执行耗时：&lt;0.1ms（很快）                               │</span>
<span class="line">│ • 关键指标：注册是否成功（通过看下一个 onVsync 是否到来） │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：很难看到（执行太快）                              │</span>
<span class="line">│ • 如果看到：会在 doFrame 结束和下一个 VSYNC 之间         │</span>
<span class="line">│ • 通常不是关注的重点（太快）                              │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-msg-do-schedule-callback-延迟回调消息" tabindex="-1"><a class="header-anchor" href="#_4-2-msg-do-schedule-callback-延迟回调消息"><span>4.2 MSG_DO_SCHEDULE_CALLBACK - 延迟回调消息</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ MSG_DO_SCHEDULE_CALLBACK                                 │</span>
<span class="line">│ （Handler 消息处理）                                     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.postCallbackDelayed()        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 内部处理：                                                │</span>
<span class="line">│ → Handler.sendMessageDelayed(MSG_DO_SCHEDULE_CALLBACK)  │</span>
<span class="line">│ → Handler.handleMessage() 处理消息                       │</span>
<span class="line">│ → Choreographer.scheduleFrameLocked()                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 当调用 postCallbackDelayed(type, action, delayMs) 时：   │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 1. 计算 dueTime = System.currentTimeMillis() + delayMs   │</span>
<span class="line">│ 2. 如果 dueTime &lt;= now（延迟已过期）：                    │</span>
<span class="line">│    • 立即将回调加入队列                                   │</span>
<span class="line">│    • 调用 scheduleFrameLocked()                          │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 3. 如果 dueTime &gt; now（还需等待）：                       │</span>
<span class="line">│    • 计算延迟时间：delay = dueTime - now                 │</span>
<span class="line">│    • 发送 Handler 消息：Handler.postDelayed(...)         │</span>
<span class="line">│    • 经过 delay 毫秒后，消息被处理                        │</span>
<span class="line">│    • MSG_DO_SCHEDULE_CALLBACK 被触发                     │</span>
<span class="line">│    • 回调被加入队列，scheduleFrameLocked() 被调用         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void postCallbackDelayed(int callbackType,              │</span>
<span class="line">│                          Runnable action,               │</span>
<span class="line">│                          long delayMillis) {             │</span>
<span class="line">│     long dueTime = System.currentTimeMillis() + delay;   │</span>
<span class="line">│     if (dueTime &lt;= SystemClock.uptimeMillis()) {         │</span>
<span class="line">│         // 延迟已过期，立即加入                           │</span>
<span class="line">│         addCallbackLocked(callbackType, action);         │</span>
<span class="line">│         scheduleFrameLocked();                           │</span>
<span class="line">│     } else {                                             │</span>
<span class="line">│         // 延迟还未到，发送 Handler 消息                  │</span>
<span class="line">│         Message msg = Message.obtain();                  │</span>
<span class="line">│         msg.what = MSG_DO_SCHEDULE_CALLBACK;             │</span>
<span class="line">│         msg.obj = new CallbackRecord(callbackType, ...); │</span>
<span class="line">│         mHandler.sendMessageAtTime(msg, dueTime);        │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│ }                                                         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ // Handler 在 UI 线程处理消息                             │</span>
<span class="line">│ void handleMessage(Message msg) {                        │</span>
<span class="line">│     if (msg.what == MSG_DO_SCHEDULE_CALLBACK) {          │</span>
<span class="line">│         CallbackRecord record = (CallbackRecord) msg.obj;│</span>
<span class="line">│         addCallbackLocked(record.type, record.action);   │</span>
<span class="line">│         scheduleFrameLocked();  // 调度下一帧             │</span>
<span class="line">│     }                                                    │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 调用时机                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 任何时刻调用 postCallbackDelayed() 时                   │</span>
<span class="line">│ • 并且 delay &gt; 0                                         │</span>
<span class="line">│ • MSG_DO_SCHEDULE_CALLBACK 在 delay 毫秒后被处理          │</span>
<span class="line">│ • 例：现在时刻 0，调用 postCallbackDelayed(..., 100ms)  │</span>
<span class="line">│    → MSG_DO_SCHEDULE_CALLBACK 在时刻 100ms 被处理         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 执行耗时：&lt;0.1ms（处理消息本身很快）                    │</span>
<span class="line">│ • 关键指标：delay 是否符合预期                            │</span>
<span class="line">│ • 关键度量：从 postCallbackDelayed 到回调执行的总时间     │</span>
<span class="line">│   = delay + 等待 VSYNC 的时间 (0-16ms)                  │</span>
<span class="line">│   = delay + 0-16ms                                      │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 外观：在 Handler 轨迹中看到的消息处理事件                │</span>
<span class="line">│ • 位置：如果有 100ms 的延迟，会有 100ms 的空白             │</span>
<span class="line">│    然后是 MSG_DO_SCHEDULE_CALLBACK 的消息处理              │</span>
<span class="line">│ • 标签：看不到明确的 &quot;MSG_DO_SCHEDULE_CALLBACK&quot; 标签      │</span>
<span class="line">│         而是看到 Handler 处理消息                          │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 典型场景：                                                │</span>
<span class="line">│ ├─ [0ms] postCallbackDelayed(..., 500ms) 被调用          │</span>
<span class="line">│ ├─ [0-500ms] UI 线程继续处理其他任务                      │</span>
<span class="line">│ ├─ [500ms] MSG_DO_SCHEDULE_CALLBACK 被处理                │</span>
<span class="line">│ ├─ [500-516ms] 等待下一个 VSYNC                          │</span>
<span class="line">│ └─ [516ms] 回调在 VSYNC 时被执行                          │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: 看到长时间的空白（如 1000ms）？                        │</span>
<span class="line">│ A: 这通常是 postCallbackDelayed 的 delay 在等待           │</span>
<span class="line">│    检查：是否有意设置了这么长的延迟？                     │</span>
<span class="line">│    如果是无意的，这可能导致性能问题                       │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: MSG_DO_SCHEDULE_CALLBACK 的执行时间比预期晚？          │</span>
<span class="line">│ A: 可能是 UI 线程繁忙，Handler 消息队列有其他任务          │</span>
<span class="line">│    检查：当前 Handler 消息队列是否有堆积                  │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 延迟回调在错误的时刻执行？                             │</span>
<span class="line">│ A: 检查计时是否正确                                       │</span>
<span class="line">│    postCallbackDelayed 的 delay 参数是毫秒                │</span>
<span class="line">│    确保没有单位转换错误                                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-buffer-stuffing-recovery-缓冲区堆积恢复" tabindex="-1"><a class="header-anchor" href="#_4-3-buffer-stuffing-recovery-缓冲区堆积恢复"><span>4.3 Buffer stuffing recovery - 缓冲区堆积恢复</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Trace 事件                                               │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 没有直接的 Trace 事件名称，但表现为：                     │</span>
<span class="line">│ • 异常的 VSYNC 间隔（变大）                               │</span>
<span class="line">│ • 某些帧的 doFrame 被跳过（没有执行）                     │</span>
<span class="line">│ • &quot;Buffer stuffing&quot; 相关的 Trace 标记（Android 12+）     │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 对应函数                                                 │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ android.view.Choreographer.onWaitForBufferRelease()     │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 由 SurfaceFlinger 调用，通过 Binder 通信                  │</span>
<span class="line">│ → SurfaceFlinger 检测到缓冲区堆积                         │</span>
<span class="line">│ → 调用 Choreographer 的 onWaitForBufferRelease()         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 函数干什么？                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ 场景：app 帧率很高（快速生成缓冲区），但 SurfaceFlinger │</span>
<span class="line">│ 还没来得及显示（缓冲区队列堆积）。                        │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 恢复机制：                                                │</span>
<span class="line">│ 1. SurfaceFlinger 检测到：前几帧的缓冲区还在队列中         │</span>
<span class="line">│ 2. SurfaceFlinger 调用：onWaitForBufferRelease(duration) │</span>
<span class="line">│ 3. Choreographer 收到通知，执行恢复：                     │</span>
<span class="line">│    • 增加帧延迟（frame delay）                            │</span>
<span class="line">│    • 跳过某些 VSYNC 信号                                  │</span>
<span class="line">│    • 暂停 app 的帧生成速度，给 SurfaceFlinger 赶上的机会 │</span>
<span class="line">│ 4. 等待足够的时间后：                                     │</span>
<span class="line">│    • 缓冲区队列被清空                                     │</span>
<span class="line">│    • 恢复正常帧率                                         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 伪代码：                                                  │</span>
<span class="line">│ void onWaitForBufferRelease(long durationNanos) {        │</span>
<span class="line">│     // durationNanos 是建议的等待时间                     │</span>
<span class="line">│     // 通常是 16ms 或 32ms（跳过 1 或 2 帧）              │</span>
<span class="line">│                                                          │</span>
<span class="line">│     // 增加帧延迟                                         │</span>
<span class="line">│     mFrameDelay = (int) (durationNanos / 1_000_000);     │</span>
<span class="line">│                                                          │</span>
<span class="line">│     // 下一帧会被延迟 mFrameDelay 毫秒                    │</span>
<span class="line">│     // 从而跳过某些 VSYNC 信号                            │</span>
<span class="line">│ }                                                         │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 调用时机                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • SurfaceFlinger 检测到缓冲区堆积时调用                   │</span>
<span class="line">│ • 缓冲区队列长度 &gt;= 2 时通常会触发                        │</span>
<span class="line">│ • Android 10+ 有这个机制                                 │</span>
<span class="line">│ • 生产设备上不常见（app 通常不会这么快）                  │</span>
<span class="line">│ • 可能在高端手机、高帧率 app（90Hz+）上看到              │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 性能指标                                                  │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 恢复时间：通常 16-32ms（跳过 1-2 帧）                   │</span>
<span class="line">│ • 频率：正常情况下很少发生                                │</span>
<span class="line">│ • 频繁发生说明：app 生成帧的速度超过显示速度              │</span>
<span class="line">│ • 原因：通常是 TRAVERSAL 或 COMMIT 太快                  │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ Perfetto 中的表现                                        │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ • 异常 1：VSYNC 间隔突然变大（如 16.67ms → 33.34ms）     │</span>
<span class="line">│   说明跳过了一个 VSYNC                                    │</span>
<span class="line">│                                                          │</span>
<span class="line">│ • 异常 2：某一帧的 doFrame 缺失                           │</span>
<span class="line">│   例：时刻 0 → 16.67 → 33.34 → 66.68（跳过 50ms 的帧）  │</span>
<span class="line">│                                                          │</span>
<span class="line">│ • 异常 3：帧时间的规律性缺口                              │</span>
<span class="line">│   如果频繁看到，说明缓冲区经常堆积                         │</span>
<span class="line">│                                                          │</span>
<span class="line">│ 例（缓冲区恢复）：                                         │</span>
<span class="line">│ ├─ [0ms] onVsync                                         │</span>
<span class="line">│ ├─ [16.67ms] onVsync                                     │</span>
<span class="line">│ ├─ [33.34ms] onVsync  ← 正常                             │</span>
<span class="line">│ ├─ [50ms] SurfaceFlinger 检测缓冲区堆积                   │</span>
<span class="line">│ │         onWaitForBufferRelease(16ms) 被调用             │</span>
<span class="line">│ ├─ [66.68ms] onVsync  ← 被跳过（被框架延迟 16ms）        │</span>
<span class="line">│ ├─ [83.35ms] onVsync  ← 恢复                             │</span>
<span class="line">│ └─ ...                                                   │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│ 关键问题诊断                                              │</span>
<span class="line">├─────────────────────────────────────────────────────────┤</span>
<span class="line">│ Q: 经常看到缓冲区堆积恢复？                               │</span>
<span class="line">│ A: 说明 app 帧生成速度过快，而 SurfaceFlinger 跟不上      │</span>
<span class="line">│    可能的原因：                                           │</span>
<span class="line">│    • TRAVERSAL 太快（内容简单）                          │</span>
<span class="line">│    • COMMIT 很快但提交太频繁                              │</span>
<span class="line">│    • SurfaceFlinger 处理过载                             │</span>
<span class="line">│                                                          │</span>
<span class="line">│ Q: 缓冲区堆积导致的掉帧如何避免？                         │</span>
<span class="line">│ A: 通常不需要做什么，这是框架的自适应机制                 │</span>
<span class="line">│    但可以：                                               │</span>
<span class="line">│    • 检查 SurfaceFlinger 的性能（通过 adb）              │</span>
<span class="line">│    • 简化 TRAVERSAL（即使很快也要注意结构）              │</span>
<span class="line">│    • 监测帧时间的一致性                                  │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="总结表-所有-trace-事件一览" tabindex="-1"><a class="header-anchor" href="#总结表-所有-trace-事件一览"><span>总结表：所有 Trace 事件一览</span></a></h2><table><thead><tr><th>序号</th><th>Trace 事件</th><th>对应函数</th><th>典型耗时</th><th>Perfetto 表现</th><th>优先级</th></tr></thead><tbody><tr><td>1</td><td>onVsync()</td><td>DisplayEventReceiver.onVsync()</td><td>&lt;0.01ms</td><td>蓝色竖线</td><td>⭐⭐⭐</td></tr><tr><td>2</td><td>doFrame()</td><td>Choreographer.doFrame()</td><td>&lt;16ms</td><td>绿/红 bar</td><td>⭐⭐⭐</td></tr><tr><td>3</td><td>INPUT</td><td>doCallbacks(CALLBACK_INPUT)</td><td>~1ms</td><td>doFrame 第 1 段</td><td>⭐</td></tr><tr><td>4</td><td>ANIMATION</td><td>doCallbacks(CALLBACK_ANIMATION)</td><td>~2-5ms</td><td>doFrame 第 2 段</td><td>⭐⭐</td></tr><tr><td>5</td><td>INSETS_ANIMATION</td><td>doCallbacks(CALLBACK_INSETS_ANIMATION)</td><td>~1ms</td><td>doFrame 第 3 段</td><td>⭐</td></tr><tr><td>6</td><td>TRAVERSAL</td><td>doCallbacks(CALLBACK_TRAVERSAL)</td><td>~8-10ms</td><td>doFrame 最长段</td><td>⭐⭐⭐</td></tr><tr><td>6.1</td><td>performMeasure</td><td>ViewRootImpl.performMeasure()</td><td>~3-4ms</td><td>TRAVERSAL 子事件</td><td>⭐⭐</td></tr><tr><td>6.2</td><td>performLayout</td><td>ViewRootImpl.performLayout()</td><td>~1-2ms</td><td>TRAVERSAL 子事件</td><td>⭐⭐</td></tr><tr><td>6.3</td><td>performDraw</td><td>ViewRootImpl.performDraw()</td><td>~4-6ms</td><td>TRAVERSAL 子事件</td><td>⭐⭐</td></tr><tr><td>7</td><td>COMMIT</td><td>doCallbacks(CALLBACK_COMMIT)</td><td>~1-2ms</td><td>doFrame 最后段</td><td>⭐⭐</td></tr><tr><td>8</td><td>scheduleVsyncLocked</td><td>Choreographer.scheduleVsyncLocked()</td><td>&lt;0.1ms</td><td>难以看到</td><td>⭐</td></tr><tr><td>9</td><td>MSG_DO_SCHEDULE_CALLBACK</td><td>Handler 消息处理</td><td>变量</td><td>Handler 轨迹</td><td>⭐⭐</td></tr><tr><td>10</td><td>Buffer stuffing recovery</td><td>onWaitForBufferRelease()</td><td>16-32ms</td><td>VSYNC 间隔变大</td><td>⭐⭐</td></tr></tbody></table><hr><h2 id="快速参考-问题诊断流程" tabindex="-1"><a class="header-anchor" href="#快速参考-问题诊断流程"><span>快速参考：问题诊断流程</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">看到 Trace 中有异常 → 按优先级检查</span>
<span class="line"></span>
<span class="line">1️⃣ onVsync() 间隔不均匀？</span>
<span class="line">   → Mode 1 vs Mode 2 问题</span>
<span class="line">   → 检查系统属性</span>
<span class="line"></span>
<span class="line">2️⃣ doFrame 是红色（&gt;16ms）？</span>
<span class="line">   → Jank 发生</span>
<span class="line">   → 深入看哪个阶段红色</span>
<span class="line"></span>
<span class="line">3️⃣ TRAVERSAL 很长？</span>
<span class="line">   → 查看 performMeasure/Layout/Draw 哪个最长</span>
<span class="line">   → 对症优化（View 树、绘制复杂度等）</span>
<span class="line"></span>
<span class="line">4️⃣ ANIMATION 波动？</span>
<span class="line">   → 检查是否使用了 System.nanoTime()</span>
<span class="line">   → 改用 Choreographer.getFrameTime()</span>
<span class="line"></span>
<span class="line">5️⃣ VSYNC 间隔变大？</span>
<span class="line">   → 缓冲区堆积恢复机制</span>
<span class="line">   → 检查是否频繁发生（频繁说明有问题）</span>
<span class="line"></span>
<span class="line">6️⃣ 长时间空白（1000ms+）？</span>
<span class="line">   → postCallbackDelayed 的 delay 在等待</span>
<span class="line">   → 正常现象，不是问题</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,36)])])}const v=n(e,[["render",d]]),r=JSON.parse('{"path":"/posts/choreographer-trace-events.html","title":"Choreographer 中的 Trace 事件 & 函数对应清单","lang":"zh-CN","frontmatter":{},"git":{"contributors":[{"name":"Kevin","username":"Kevin","email":"kevin@example.com","commits":1,"url":"https://github.com/Kevin"}],"changelog":[{"hash":"04df935ed0733100736ded74620d20590491252a","time":1779444869000,"email":"kevin@example.com","author":"Kevin","message":"docs: 新增 Choreographer Trace 事件完整清单（独立文章）"}]},"filePathRelative":"posts/choreographer-trace-events.md"}');export{v as comp,r as data};
